import fs from "node:fs";
import path from "node:path";
import { loadEnv } from "../src/config.mjs";
import { telegramApi } from "../src/telegramApi.mjs";

await loadEnv();

const base = path.join(
  "D:",
  ".1 Work Stations",
  "RootMC",
  "Server Handoffs",
  "Ava Ivy",
  "data",
);

function readJsonl(p) {
  if (!fs.existsSync(p)) return [];
  const text = fs.readFileSync(p, "utf8");
  const lines = text.split(/\r?\n/).filter((l) => l.trim());
  const out = [];
  for (const l of lines) {
    try {
      out.push(JSON.parse(l));
    } catch {
      // concatenated objects without newlines — try streaming parse
      let i = 0;
      while (i < l.length) {
        while (i < l.length && /\s/.test(l[i])) i++;
        if (i >= l.length) break;
        try {
          const { value, index } = JSON.parse(l.slice(i), (k, v, { source }) => v);
          // fallback: find matching braces
        } catch {
          /* use brace scan below */
        }
        if (l[i] !== "{") {
          out.push({ __raw: l.slice(i, i + 80) });
          break;
        }
        let depth = 0;
        let inStr = false;
        let esc = false;
        let j = i;
        for (; j < l.length; j++) {
          const c = l[j];
          if (inStr) {
            if (esc) esc = false;
            else if (c === "\\") esc = true;
            else if (c === '"') inStr = false;
            continue;
          }
          if (c === '"') inStr = true;
          else if (c === "{") depth++;
          else if (c === "}") {
            depth--;
            if (depth === 0) {
              j++;
              break;
            }
          }
        }
        try {
          out.push(JSON.parse(l.slice(i, j)));
        } catch (e) {
          out.push({ __raw: l.slice(i, i + 120), err: String(e.message) });
          break;
        }
        i = j;
      }
    }
  }
  return out;
}

let updates = [];
try {
  updates = await telegramApi(
    "getUpdates",
    {
      offset: -80,
      limit: 80,
      timeout: 0,
      allowed_updates: ["message", "edited_message", "my_chat_member"],
    },
    {},
  );
} catch (e) {
  console.log("UPD_ERR", e.message);
}
console.log("=== getUpdates", updates.length);
for (const u of updates) {
  const m = u.message || u.edited_message;
  if (!m) {
    console.log("upd", u.update_id, Object.keys(u));
    continue;
  }
  console.log(
    JSON.stringify({
      chat: m.chat?.id,
      mid: m.message_id,
      from: m.from?.id,
      uname: m.from?.username || m.from?.first_name,
      text: String(m.text || m.caption || "").slice(0, 400),
      reply_to: m.reply_to_message?.message_id || null,
      media: !!(m.photo || m.video || m.animation || m.document || m.sticker),
    }),
  );
}

const files = [
  "telegram/groups/-1003868178598/inbound.jsonl",
  "logs/inbound.jsonl",
  "logs/outbound.jsonl",
  "training/utterances.jsonl",
];
for (const rel of files) {
  const p = path.join(base, rel);
  if (!fs.existsSync(p)) {
    console.log("MISSING", rel);
    continue;
  }
  const st = fs.statSync(p);
  console.log(
    "\nFILE",
    rel,
    "bytes",
    st.size,
    "mtime",
    st.mtime.toISOString(),
  );
}

const vault = readJsonl(
  path.join(base, "telegram/groups/-1003868178598/inbound.jsonl"),
);
console.log("\n=== FF VAULT", vault.length, "last 40");
for (const o of vault.slice(-40)) {
  if (o.__raw) {
    console.log("BAD", o.__raw, o.err || "");
    continue;
  }
  console.log(
    JSON.stringify({
      at: o.at,
      event: o.event,
      from: o.fromId,
      mid: o.messageId || o.mid || o.id,
      preview: String(o.preview || o.content || "").slice(0, 400),
    }),
  );
}

const inbound = readJsonl(path.join(base, "logs/inbound.jsonl"));
const tgIn = inbound.filter(
  (m) =>
    !m.__raw &&
    (String(m.channelId || "").includes("tg:") ||
      String(m.surface || "") === "telegram" ||
      String(m.channelId || "").includes("6644482344") ||
      String(m.channelId || "").includes("3868178598")),
);
console.log("\n=== INBOUND TG", tgIn.length, "last 35");
for (const m of tgIn.slice(-35)) {
  console.log(
    JSON.stringify({
      id: m.messageId,
      ch: m.channelId,
      from: m.authorId,
      name: m.authorName,
      c: String(m.content || "").slice(0, 350),
      ref: m.refId,
      at: m.at || m.ts,
    }),
  );
}

const outbound = readJsonl(path.join(base, "logs/outbound.jsonl"));
const tgOut = outbound.filter(
  (m) =>
    !m.__raw &&
    (String(m.channelId || "").includes("tg:") ||
      String(m.channelId || "").includes("3868178598") ||
      String(m.channelId || "").includes("6644482344")),
);
console.log("\n=== OUTBOUND TG", tgOut.length, "last 30");
for (const m of tgOut.slice(-30)) {
  console.log(
    JSON.stringify({
      id: m.messageId,
      ch: m.channelId,
      kind: m.kind,
      c: String(m.content || "").slice(0, 300),
      at: m.at || m.ts,
      ref: m.refId || m.replyTo,
    }),
  );
}

const utt = readJsonl(path.join(base, "training/utterances.jsonl"));
const tgU = utt.filter(
  (u) =>
    !u.__raw &&
    (String(u.surface || "") === "telegram" ||
      String(u.channelId || "").includes("tg:") ||
      String(u.channelId || "").includes("3868178598") ||
      String(u.channelId || "").includes("6644482344")),
);
console.log("\n=== UTTERANCES TG", tgU.length, "last 20");
for (const u of tgU.slice(-20)) {
  console.log(
    JSON.stringify({
      id: u.messageId || u.id,
      ch: u.channelId,
      from: u.authorId || u.fromId,
      c: String(u.content || u.text || u.preview || "").slice(0, 300),
      at: u.at || u.ts,
    }),
  );
}

